import { jest } from '@jest/globals';
import { Command } from 'commander';
const postMock = jest.fn();
jest.unstable_mockModule('axios', () => ({
    default: { post: postMock },
    post: postMock
}));
describe('sync command', () => {
    afterEach(() => {
        jest.resetModules();
        jest.clearAllMocks();
        postMock.mockReset();
    });
    it('exits when disabled', async () => {
        const logSpy = jest.spyOn(console, 'log').mockImplementation(() => { });
        const readConfig = jest.fn().mockReturnValue({ cloudSync: { enabled: false } });
        jest.unstable_mockModule('../src/utils/config.js', () => ({
            readConfig,
            getHistoryStorePath: jest.fn()
        }));
        jest.unstable_mockModule('../src/utils/history.js', () => ({ loadHistory: jest.fn().mockReturnValue([]) }));
        const { registerSync } = await import('../src/commands/sync.js');
        const program = new Command();
        registerSync(program);
        await program.parseAsync(['node', 'test', 'sync']);
        expect(logSpy).toHaveBeenCalledWith('Cloud sync disabled in config.');
    });
    it('posts payload when enabled', async () => {
        const readConfig = jest.fn().mockReturnValue({
            cloudSync: { enabled: true, endpoint: 'https://api.example.com/sync', apiKey: 'k' }
        });
        const loadHistory = jest.fn().mockReturnValue([{ command: 'test', timestamp: 1, durationMs: 5 }]);
        jest.unstable_mockModule('../src/utils/config.js', () => ({
            readConfig,
            getHistoryStorePath: jest.fn()
        }));
        jest.unstable_mockModule('../src/utils/history.js', () => ({ loadHistory }));
        postMock.mockResolvedValue({ data: { id: 'sync123' } });
        const logSpy = jest.spyOn(console, 'log').mockImplementation(() => { });
        const { registerSync } = await import('../src/commands/sync.js');
        const program = new Command();
        registerSync(program);
        await program.parseAsync(['node', 'test', 'sync']);
        expect(postMock).toHaveBeenCalledWith('https://api.example.com/sync', expect.objectContaining({ history: expect.any(Array) }), expect.objectContaining({ headers: expect.objectContaining({ Authorization: 'Bearer k' }) }));
        expect(logSpy).not.toHaveBeenCalledWith('Cloud sync endpoint missing in config.');
    });
});
